<script setup lang="ts">
import{memberTypeName,memberStatusName}from'../membership';import{computed,reactive,ref}from'vue';import{useRoute,useRouter}from'vue-router';import{ElMessageBox}from'element-plus';import{state,refreshMine,refreshPublic,logout}from'../store';import{api,run,resetCsrf}from'../api';import type{Row,User}from'../types';import Icon from'../components/Icon.vue';import Status from'../components/Status.vue';import RepairTimeline from'../components/RepairTimeline.vue';import{date,canCheckin}from'../utils'
const route=useRoute(),router=useRouter(),tab=ref(['activities','loans','repairs','profile'].includes(String(route.query.tab))?String(route.query.tab):'activities'),busy=ref(false),checkinRow=ref<Row|null>(null),checkinCode=ref(''),ticket=ref<Row|null>(null)
const profile=reactive({name:state.user?.name||'',email:state.user?.email||'',department:state.user?.department||'',bio:state.user?.bio||''}),password=reactive({oldPassword:'',newPassword:''})
const counters=computed(()=>[{label:'参与活动',value:state.mine.registrations.length,icon:'calendar',tab:'activities'},{label:'借用中的器材',value:state.mine.loans.filter(l=>['APPROVED','RETURN_PENDING'].includes(l.status)).reduce((n,l)=>n+l.quantity,0),icon:'package',tab:'loans'},{label:'处理中工单',value:state.mine.repairs.filter(t=>['OPEN','PROCESSING'].includes(t.status)).length,icon:'wrench',tab:'repairs'}])
async function action(path:string,method:string,message:string,confirmation?:string){if(confirmation&&!await ElMessageBox.confirm(confirmation,'操作确认',{confirmButtonText:'确认',cancelButtonText:'取消',type:'warning'}).then(()=>true).catch(()=>false))return;busy.value=true;await run(async()=>{await api(path,method);await Promise.all([refreshMine(),refreshPublic()])},message);busy.value=false}
async function submitCheckin(){if(!checkinRow.value)return;busy.value=true;await run(async()=>{await api(`/registrations/${checkinRow.value!.id}/checkin`,'POST',{code:checkinCode.value});await refreshMine();checkinRow.value=null},'签到成功，享受活动吧');busy.value=false}
async function saveProfile(){if(!profile.name.trim()||!profile.email.trim()||!profile.department.trim())return;busy.value=true;await run(async()=>state.user=await api<User>('/me/profile','PUT',profile),'个人资料已更新');busy.value=false}
async function savePassword(){if(password.newPassword.length<8)return;busy.value=true;await run(async()=>{await api('/me/password','PUT',password);state.user=null;resetCsrf();router.replace('/login')},'密码已更新，请重新登录');busy.value=false}
</script>
<template><div class="page-content" v-if="state.user"><div class="page-heading"><div><div class="eyebrow">记录属于你的征途记录</div><h1>成员中心<span class="greeting-dot">.</span></h1><p>每一次参与，都在书写属于你的征途记录。</p></div><el-button @click="run(async()=>{await logout();router.push('/')},'已退出登录')"><Icon name="logout" :size="16"/>退出登录</el-button></div><section class="profile-banner panel"><span class="profile-avatar">{{state.user.name[0]}}</span><div><h2>{{state.user.name}}<el-tag size="small" type="success">{{['ADMIN','SUPER_ADMIN'].includes(state.user.role)?(state.user.role==='SUPER_ADMIN'?'超级管理员':'管理员'):memberTypeName(state.mine.member?.memberType)+'成员'}}</el-tag></h2><p>{{state.user.department}} · 学号 {{state.user.studentNo}}</p><span>{{state.user.bio||'保持好奇，去遇见更大的世界。'}}</span></div><button class="outline-link" @click="tab='profile'"><Icon name="settings" :size="16"/>编辑个人资料</button></section><section class="panel member-identity-panel"><strong>加入身份：{{memberTypeName(state.mine.member?.memberType||state.user.joinType)}}</strong><el-tag :type="state.mine.member?.memberStatus==='APPROVED'?'success':'info'">{{memberStatusName(state.mine.member?.memberStatus)}}</el-tag><span v-if="state.mine.member?.clubDivision">{{state.mine.member.clubDivision}}</span><p>{{state.mine.member?.memberNote||'身份权益按审核结果生效。如需变更类别、部门或成员资料，请联系管理员。'}}</p></section><div class="stats-grid center-stats"><button v-for="c in counters" :key="c.tab" class="stat-card" @click="tab=c.tab"><span class="stat-icon green"><Icon :name="c.icon" :size="23"/></span><div><span class="stat-label">{{c.label}}</span><b>{{c.value}}</b></div><Icon name="right" :size="16"/></button></div><section class="panel center-panel" v-loading="busy"><el-tabs v-model="tab">
<el-tab-pane label="活动与签到" name="activities"><el-table :data="state.mine.registrations" stripe empty-text="还没有活动记录，去报名一场精彩活动吧"><el-table-column label="活动" min-width="230"><template #default="{row}"><b>{{row.activity.title}}</b><p class="small muted">{{row.activity.location}} · {{date(row.activity.startsAt,true)}}</p><el-tag v-if="row.activity.status==='CANCELLED'" size="small" type="danger">活动已取消</el-tag></template></el-table-column><el-table-column label="签到记录" min-width="165"><template #default="{row}"><el-tag v-if="row.checkedInAt" type="success" size="small">已签到</el-tag><span v-else class="muted">未签到</span><p v-if="row.checkedInAt" class="small muted">{{date(row.checkedInAt,true)}}</p></template></el-table-column><el-table-column label="操作" min-width="210"><template #default="{row}"><el-button v-if="!row.checkedInAt" type="primary" size="small" :disabled="!canCheckin(row.activity)" @click="checkinRow=row;checkinCode=''">现场签到</el-button><el-button v-if="!row.checkedInAt&&(new Date(row.activity.startsAt).getTime()>Date.now()||row.activity.status==='CANCELLED')" type="danger" link @click="action(`/registrations/${row.id}`,'DELETE','已取消报名','确认取消本次活动报名？')">取消报名</el-button></template></el-table-column></el-table><p class="table-help">签到窗口：活动开始前 30 分钟至活动结束。请向现场负责人获取签到码。</p></el-tab-pane>
<el-tab-pane label="器材借还" name="loans"><el-table :data="state.mine.loans" stripe empty-text="暂无借用记录"><el-table-column label="器材 / 用途" min-width="220"><template #default="{row}"><b>{{row.equipment.name}} × {{row.quantity}}</b><p class="small muted">{{row.purpose}}</p><p v-if="row.reviewNote" class="small muted">审核：{{row.reviewNote}}</p></template></el-table-column><el-table-column label="预计归还" min-width="130"><template #default="{row}">{{row.dueDate}}<el-tag v-if="row.overdue" type="danger" size="small">已逾期</el-tag></template></el-table-column><el-table-column label="状态" min-width="120"><template #default="{row}"><Status :value="row.status"/></template></el-table-column><el-table-column label="操作" min-width="150"><template #default="{row}"><el-button v-if="row.status==='PENDING'" type="danger" link @click="action(`/loans/${row.id}/cancel`,'POST','已取消借用申请','确认取消申请？')">取消申请</el-button><el-button v-if="row.status==='APPROVED'" type="primary" size="small" @click="action(`/loans/${row.id}/return`,'POST','归还申请已提交，请送交器材等待验收','已准备好归还器材？提交后请送至器材存放地点验收。')">申请归还</el-button><span v-if="row.status==='RETURN_PENDING'" class="muted small">等待管理员验收</span></template></el-table-column></el-table></el-tab-pane>
<el-tab-pane label="维修工单" name="repairs"><el-table :data="state.mine.repairs" stripe empty-text="暂无维修记录"><el-table-column prop="title" label="工单标题" min-width="220"/><el-table-column prop="location" label="地点" min-width="150"/><el-table-column label="状态" width="110"><template #default="{row}"><Status :value="row.status"/></template></el-table-column><el-table-column label="操作" width="120"><template #default="{row}"><el-button type="primary" link @click="ticket=row">查看进度</el-button></template></el-table-column></el-table><router-link class="empty-action" to="/repairs">提交新的维修工单 <Icon name="arrow" :size="15"/></router-link></el-tab-pane>
<el-tab-pane label="个人资料" name="profile"><div class="profile-forms"><el-form label-position="top" @submit.prevent="saveProfile"><h3>基本资料</h3><div class="form-grid"><el-form-item label="姓名" required><el-input v-model="profile.name" maxlength="50"/></el-form-item><el-form-item label="邮箱" required><el-input v-model="profile.email" type="email" maxlength="120"/></el-form-item></div><el-form-item label="院系" required><el-input v-model="profile.department" maxlength="100"/></el-form-item><el-form-item label="个人简介"><el-input v-model="profile.bio" type="textarea" :rows="3" maxlength="500" show-word-limit/></el-form-item><el-button type="primary" native-type="submit">保存资料</el-button></el-form><el-form label-position="top" @submit.prevent="savePassword"><h3>账号安全</h3><p class="muted small">修改密码后，所有设备上的登录会话都会失效。</p><el-form-item label="原密码" required><el-input v-model="password.oldPassword" type="password" show-password autocomplete="current-password"/></el-form-item><el-form-item label="新密码（至少 8 位）" required><el-input v-model="password.newPassword" type="password" show-password autocomplete="new-password" maxlength="64"/></el-form-item><el-button type="primary" native-type="submit" :disabled="!password.oldPassword||password.newPassword.length<8">更新密码</el-button></el-form></div></el-tab-pane></el-tabs></section></div>
<el-dialog :model-value="!!checkinRow" @update:model-value="(v:boolean)=>{if(!v)checkinRow=null}" title="活动现场签到" width="min(450px, 94vw)"><p>{{checkinRow?.activity.title}}</p><el-input v-model="checkinCode" placeholder="输入现场签到码" maxlength="32" @keyup.enter="submitCheckin"/><template #footer><el-button type="primary" :loading="busy" :disabled="!checkinCode.trim()" @click="submitCheckin">确认签到</el-button></template></el-dialog><el-dialog :model-value="!!ticket" @update:model-value="(v:boolean)=>{if(!v)ticket=null}" title="工单进度" width="min(650px, 94vw)"><RepairTimeline v-if="ticket" :ticket="ticket"/></el-dialog></template>
